#[derive(Debug, PartialEq)]
pub enum WithdrawError {
    NotPositive,
    Insufficient,
}

pub fn withdraw(balance: i64, amount: i64) -> Result<i64, WithdrawError> {
    if amount <= 0 {
        return Err(WithdrawError::NotPositive);
    }
    if amount > balance {
        return Err(WithdrawError::Insufficient);
    }
    Ok(balance - amount)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_errors() {
        assert_eq!(withdraw(100, 30), Ok(70));
        assert_eq!(withdraw(50, 50), Ok(0));
        assert_eq!(withdraw(100, 0), Err(WithdrawError::NotPositive));
        assert_eq!(withdraw(10, 30), Err(WithdrawError::Insufficient));
    }
}
